name: Merge Queue Cleanup

on:
  schedule:
    - cron: '*/5 * * * *'

permissions:
  pull-requests: write
  contents: read

jobs:
  cleanup:
    runs-on: ubuntu-latest
    concurrency:
      group: merge-queue-cleanup
      cancel-in-progress: true
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Clean up workspace
        uses: tenstorrent/tt-metal/.github/actions/cleanup@main
        with:
          path: .

      - name: Remove UNMERGEABLE PRs from merge queue
        uses: actions/github-script@v6
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const owner = context.repo.owner;
            const repo = context.repo.repo;
            const octokit = github;

            // Fetch merge queue entries
            const { data: queue } = await octokit.request('GET /repos/{owner}/{repo}/merges?queue', {
              owner,
              repo,
            });

            if (!queue || queue.length === 0) {
              console.log('Merge queue is empty.');
              return;
            }

            for (const entry of queue) {
              if (entry.status === 'UNMERGEABLE') {
                const prNumber = entry.pull_request_number;
                console.log(`Removing PR #${prNumber} (UNMERGEABLE) from merge queue.`);

                // Remove the PR from the merge queue
                await octokit.request('POST /repos/{owner}/{repo}/merges?queue', {
                  owner,
                  repo,
                  pull_request_number: prNumber,
                  action: 'remove',
                });

                // Post a comment on the PR
                const commentBody = `⚠️ This pull request was removed from the merge queue because it was marked **UNMERGEABLE**. Please rebase onto the latest base branch and re-open the pull request.`;
                await octokit.request('POST /repos/{owner}/{repo}/issues/{issue_number}/comments', {
                  owner,
                  repo,
                  issue_number: prNumber,
                  body: commentBody,
                });
              }
            }
